'use strict';
const utcToday=()=>new Date().toISOString().slice(0,10);
let historicalResults=null,selectedHistoryRule='',dummyDraft=null,publicationFilter='current';
let state=null,view='overview',mode='live',day=utcToday(),knownAt='',labCache=null,manualNotice='',reviewerName='',employeeSearch='',employeeFilter='ACTUAL',monitorTimer=null;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v===null||v===undefined?'—':Number(v).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const pretty=s=>String(s).replaceAll('_',' ').toLowerCase().replace(/^./,c=>c.toUpperCase());
const short=id=>(id||'').slice(0,12);
const colors={NON_COMPLIANT:'red',COMPLIANT:'green',REVIEW_REQUIRED:'amber',INSUFFICIENT_DATA:'amber',APPROVED:'green',REJECTED:'',ACKNOWLEDGED:''};
const chip=(s,label)=>`<span class="chip ${colors[s]||''}">${esc(label||pretty(s))}</span>`;
const query=(extra={})=>new URLSearchParams({mode,date:day,...(knownAt?{known_at:knownAt}:{}),...extra}).toString();
async function api(path,extra={}){const r=await fetch(path+'?'+query(extra));const body=await r.json();if(!r.ok)throw Error(body.error||'Request failed');return body;}
async function post(path,body={}){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-Atlas-CSRF':state.csrf},body:JSON.stringify({mode,date:day,...body})});const result=await r.json();if(!r.ok)throw Error(result.error||'Request failed');return result;}
function error(err){$('#error').textContent=err.message||String(err);$('#error').hidden=false;}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,4500);}
function modal(body){$('#dialog-content').innerHTML=body;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();}
function head(kicker,title,sub,action=''){return `<div class="page-head"><div><span class="eyebrow">${esc(kicker)}</span><h1>${esc(title)}</h1><p class="lead">${esc(sub)}</p></div>${action}</div>`;}
function metric(label,value,note,color=''){return `<div class="metric"><div class="metric-label">${esc(label)}</div><div class="metric-value ${color}">${esc(value)}</div><p>${esc(note)}</p></div>`;}

function retainedNotice(){const info=state.retention;return info?`<div class="alert-box"><b>Last approved results · ${esc(info.saved_date)}</b><p>${esc(info.message)} Saved wages and decisions below are unchanged; they do not confirm current compliance.</p><details><summary>See current problems (${info.issues.length})</summary>${info.issues.map(i=>`<p><button class="link-button" data-employee="${esc(i.employee_id)}">${esc(i.employee_id)} ↗</button> · ${esc(i.explanation)}${i.input_changed?' Employee inputs changed since this saved result.':''}</p>`).join('')}</details>${info.source_count?'<button class="link-button" data-view="review">Inspect source updates →</button>':''}</div>`:'';}
function employeeExportUrl(){return historicalResults?'/api/saved-results?'+query({id:selectedHistoryRule,download:'1'}):'/api/export?'+query();}
function updateExportLink(){const link=$('#export-link');link.href=employeeExportUrl();link.textContent=historicalResults?'↓ Export selected inspection':'↓ Export employee results';}
function currentEmployeeIssue(id){if(historicalResults)return '';const issue=state.retention?.issues.find(i=>i.employee_id===id);return issue?`<div class="alert-box"><b>Current check: ${esc(pretty(issue.decision_state))}</b><p>${esc(issue.explanation)}${issue.input_changed?' Employee inputs changed since this saved result.':''}</p><p>The wage and decision below belong to the saved result.</p></div>`:'';}
function metrics(){
 const c=state.summary.counts,needs=(c.REVIEW_REQUIRED||0)+(c.INSUFFICIENT_DATA||0);
 const salary=countReason('SALARY_CONVERSION_UNAPPROVED'),future=countReason('FUTURE_START_CONFLICT');
 const source=countReason('PENDING_SOURCE_REVIEW')+countReason('SOURCE_HEALTH_REVIEW')+countReason('CONFLICTING_APPROVED_RULES');
 const sourceItems=state.retained_results_date?0:currentReviewQueue().blocking.length,other=Math.max(0,needs-salary-future-source);
 const reasons=[source?`${source} source-blocked`:sourceItems?`${sourceItems} source ${sourceItems===1?'item':'items'} pending`:(state.retained_results_date?'Saved results':'Sources clear'),
                salary?`${salary} salary policy`:null,future?`${future} future-start`:null,other?`${other} other review`:null].filter(Boolean).join(' · ');
 return `<div class="metrics result-metrics">${metric('Below approved minimum',c.NON_COMPLIANT||0,'Employees requiring wage investigation','red')}${metric('Meets approved minimum',c.COMPLIANT||0,'Supported by approved rules','green')}${metric('Needs a decision',needs,reasons,'amber')}</div>`;
}
function currentReviewQueue(){
 const pending=state.candidates.filter(c=>c.state==='REVIEW_REQUIRED');
 const blocking=pending.filter(c=>!c.policy_applied&&['RATE_REVIEW','REVIEW_REQUIRED','SECURITY_REVIEW','INTERPRETATION'].includes(c.classification)&&(!c.effective_from||c.effective_from<=day)&&(!c.effective_to||day<c.effective_to));
 return {blocking,other:state.candidates.filter(c=>!blocking.includes(c))};
}
function countReason(code){return state.results.filter(r=>r.reason_code===code).length;}
function reviewSummary(c){if(c.policy_applied)return c.source_rule_id==='BDL-2026-0121'?'Existing logic automatically selects the higher applicable approved federal or state rate. No additional review is needed for this unchanged guidance.':'Existing logic uses physical work location, including qualifying remote work. No additional review is needed for this unchanged guidance.';return c.source_rule_id==='AFWA-2026-0038'?'Employer-size coverage threshold changed from 24 to 25; the supplied file has no employer headcount.':c.reason;}
function publicationType(c){return ({CORRECTION:'Coverage correction',GUIDANCE:'Interpretation',PROPOSAL:'Proposal, not law',NEWS:'Unrelated news'})[c.kind]||pretty(c.classification);}
function decisionReason(r){return ({PENDING_SOURCE_REVIEW:'Source interpretation awaiting review',SALARY_CONVERSION_UNAPPROVED:'Salary conversion policy needed',FUTURE_START_CONFLICT:'Active status conflicts with future start',SOURCE_HEALTH_REVIEW:'Source check needs attention',BELOW_APPROVED_FLOOR:'Below approved floor',MEETS_APPROVED_FLOOR:'Meets approved floor'})[r.reason_code]||r.reason_code?.replaceAll('_',' ').toLowerCase()||'';}
function wageCell(r,showProxies=false){const c=r.analysis_context||{};if(r.actual_hourly_wage!==null)return `${fmt(r.actual_hourly_wage)}<small>Recorded AST / hour</small>`;if(showProxies&&c.indicative_salary_hourly!==null&&c.indicative_salary_hourly!==undefined)return `~${fmt(c.indicative_salary_hourly)}<small>Salary proxy · not actual hourly pay</small>`;return r.employee_input?.pay_basis==='Annual Salary'?'—<small>Annual salary · needs review</small>':'—<small>No recorded hourly value</small>';}
function floorCell(r){const c=r.analysis_context||{};if(r.controlling_minimum_wage!==null)return `${fmt(r.controlling_minimum_wage)}<small>${esc(r.controlling_jurisdiction)} · controlling</small>`;const pending=(c.pending_rate_candidates||[]).map(p=>`${esc(p.amount)} ${esc(p.jurisdiction)}`).join(', ');if(c.approved_reference_floor!==null&&c.approved_reference_floor!==undefined)return `${fmt(c.approved_reference_floor)}<small>${pending?'Last approved reference · not final':'Approved floor · wage review'}</small>${pending?`<small>Pending: ${pending}</small>`:''}`;return `—<small>${pending?'Pending: '+pending:'No approved floor for this date'}</small>`;}
function table(rows,compact=false,showProxies=false){return `<div class="table-scroll"><table><thead><tr><th>Employee / work location</th><th>Hourly wage</th><th>Required floor</th><th>Decision</th>${compact?'':'<th>Weekly shortfall</th>'}<th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="link-button" data-employee="${esc(r.employee_id)}">${esc(r.employee_id)}</button><small>${esc(r.work_jurisdiction)}</small></td><td>${wageCell(r,showProxies)}</td><td>${floorCell(r)}</td><td>${chip(r.decision_state)}<small>${esc(decisionReason(r))}</small></td>${compact?'':`<td>${fmt(r.estimated_weekly_underpayment)}<small>${r.estimated_weekly_underpayment===null?'Not decided':'AST estimate'}</small></td>`}<td><button class="link-button" data-employee="${esc(r.employee_id)}" aria-label="Inspect ${esc(r.employee_id)}">↗</button></td></tr>`).join('')}</tbody></table></div>`;}
function sourceDetailsContent(){
 if(mode!=='live')return '';
 const monitor=state.monitor||{};
 const monitorError=checkOutcome(monitor);
 const sources=[['federal','Asterian federal'],['bellwether','Bellwether state']];
 const cards=sources.map(([source,label])=>{
  const candidate=state.candidates.filter(c=>c.source===source&&c.kind==='DAILY_RATE'&&c.effective_from===day)
   .sort((a,b)=>b.discovered_at.localeCompare(a.discovered_at))[0];
  const fetch=state.fetches.find(f=>f.source===source);
  const captured=!!candidate&&!!fetch&&fetch.status!=='ERROR'&&candidate.seen_in_latest_check;
  const checked=fetch?.fetched_at?new Date(fetch.fetched_at).toLocaleString():null;
  const evidence=candidate?`<button class="link-button" data-rule="${esc(candidate.id)}">Inspect saved evidence ↗</button>`:'';
  return `<article class="live-rate-card"><div class="live-rate-head"><h3>${esc(label)}</h3>${chip(candidate?.state||'INSUFFICIENT_DATA',candidate?.state==='APPROVED'?'Approved':candidate?.state==='REJECTED'?'Rejected':candidate?'Human review required':'No current rate')}</div><div class="live-rate-value">${candidate?fmt(candidate.amount):'—'} <small>AST / hour</small></div><p>Effective ${esc(candidate?.effective_from||day)} · ${captured?'Page captured and parsed':fetch?.status==='ERROR'?'Latest fetch failed':'Current page needs checking'}</p><p>${checked?'Last checked '+esc(checked):'No source check recorded'}${fetch?.status==='CHANGED'?' · Page changed since the previous check':''}</p>${evidence}</article>`;
 }).join('');
 return `<div class="source-popover"><div class="live-source-head"><div><h2>Latest website rates</h2><p>${esc(day)} · New rates need approval before they change employee results.</p></div></div>${monitorError}<div class="live-rate-grid">${cards}</div><p class="source-schedule-note">15-minute checks are ${monitor.running?'on':'off'}. Automatic checks run only while this Atlas server is open.${monitor.next_check_at?' Next check: '+esc(new Date(monitor.next_check_at).toLocaleString())+'.':''}</p></div>`;
}
function renderSourceBar(){
 const bar=$('#source-bar'),m=state.monitor||{};
 const opened=new Set([...bar.querySelectorAll('details[open]')].map(d=>d.querySelector('summary')?.textContent));
 const focus=document.activeElement?.closest('#source-bar summary')?.textContent;
 const failed=m.last_error||failedReevaluations(m).length||(m.last_result?.checks||[]).some(c=>c.status==='ERROR')||Object.keys(state.health||{}).length;
 const latest=state.fetches.map(f=>f.fetched_at).filter(Boolean).sort().at(-1);
 const seconds=m.started_at?Math.max(0,Math.floor((Date.now()-Date.parse(m.started_at))/1000)):0;
 const status=m.checking?`Checking · ${seconds}s`:m.stopping?'Stopping checks':failed?'Check needs attention':m.last_result?.checks.some(c=>c.status!=='UNCHANGED')?'Source updates found':latest?`Checked ${new Date(latest).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`:'Not checked yet';
 bar.innerHTML=`<div class="source-bar-label"><strong>Live websites</strong><span class="source-bar-status ${failed?'check-error':''}" role="status">${esc(status)}</span></div><div class="source-bar-actions"><button class="primary small" data-action="fetch" ${m.checking?'disabled':''}>${m.checking?'Checking…':'Check sites ↻'}</button><button class="secondary small" data-action="${m.running?'monitor-stop':'monitor-start'}" ${m.stopping||(!m.running&&m.checking)?'disabled':''}>${m.running?'Stop 15-min checks':'Start 15-min checks'}</button><details class="source-details"><summary>Rates &amp; details</summary>${sourceDetailsContent()}</details></div>`;
 bar.querySelectorAll('details').forEach(d=>{if(opened.has(d.querySelector('summary')?.textContent))d.open=true;});
 if(focus)[...bar.querySelectorAll('summary')].find(s=>s.textContent===focus)?.focus({preventScroll:true});
}
document.addEventListener('click',event=>{const panel=$('#source-bar .source-details');if(panel?.open&&!$('#source-bar').contains(event.target))panel.open=false;});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#detail-dialog').open){const panel=$('#source-bar .source-details');if(panel?.open){panel.open=false;panel.querySelector('summary').focus();}}});
function failedReevaluations(m){return (state?.jobs??m.last_result?.jobs??[]).filter(j=>j.state==='FAILED');}
function checkTitle(m){
 if(m.last_error)return 'Check failed';
 const checks=m.last_result?.checks||[];
 if(checks.some(c=>c.status==='ERROR'))return 'Check completed with source errors';
 if(failedReevaluations(m).length)return 'Check completed — some re-evaluations failed';
 return checks.length&&checks.every(c=>c.status==='UNCHANGED')?'Check complete — no changes found':'Check complete — source updates found';
}
function checkOutcome(m){
 if(m.checking){const seconds=m.started_at?Math.max(0,Math.floor((Date.now()-Date.parse(m.started_at))/1000)):0;return `<div class="alert-box" role="status"><b>Checking both websites…</b><p>${seconds} seconds elapsed. Results below are from the last saved check. This panel updates automatically when the check finishes.</p></div>`;}
 if(m.last_error)return `<div class="alert-box check-error" role="alert"><b>Check failed</b><p>${esc(m.last_error)}</p><p>The check did not finish. You can retry using the button above.</p></div>`;
 const failed=failedReevaluations(m);
 const jobWarning=failed.length?`<div class="alert-box" role="alert"><b>${failed.length} re-evaluation ${failed.length===1?'job needs':'jobs need'} retry</b><p>Some employee results could not be recalculated. Saved results remain available. Retry the website check to retry this work.</p><button class="secondary small" data-action="fetch">Retry check</button><details><summary>Failure details</summary>${failed.map(j=>`<p>${esc(j.jurisdiction||'Re-evaluation')} · ${esc(j.effective_from||j.due_date||'stored dates')}<br>${esc(j.error)}<br><span class="mono">${esc(j.id||j.job_id)}</span></p>`).join('')}</details></div>`:'';
 const r=m.last_result;if(!r)return jobWarning;
 const names={federal:'Asteria',bellwether:'Bellwether'};
 const details=r.checks.map(c=>`${names[c.source]||c.source}: ${c.status==='UNCHANGED'?'no change':c.status==='ERROR'?'failed':c.status==='INITIAL'?'first capture':'updated'}`).join(' · ');
 const partial=failed.length||r.checks.some(c=>c.status==='ERROR');
 return `<details class="check-outcome ${partial?'alert-box':'review-empty'}" ${partial?'open':''}><summary>${esc(checkTitle(m))}</summary><div class="check-outcome-body"><p>${esc(details)}. Check started ${esc(new Date(r.checked_at).toLocaleString())}.</p><p>${r.summary.total} current employee results evaluated and archived.${r.checks.some(c=>c.new_candidates?.length)?' New source items are available in Rule review.':''}</p><details><summary>Archive details</summary><span class="mono">${esc(r.manifest)}</span></details></div></details>`+jobWarning;
}
function scheduleMonitorRefresh(){
 clearTimeout(monitorTimer);
 if(mode!=='live'||!state?.monitor?.checking&&!state?.monitor?.stopping)return;
 monitorTimer=setTimeout(async()=>{
  try{
   const previous=state.monitor;state.monitor=await api('/api/monitor/status');
   if(!state.monitor.checking&&!state.monitor.stopping){await load();if(previous.checking)toast(checkTitle(state.monitor));}
   else renderSourceBar();
  }catch(e){error(Error('Could not refresh check status; retrying automatically. '+e.message));}
  finally{scheduleMonitorRefresh();}
 },1000);
}
function overview(){
 const queue=currentReviewQueue().blocking;
 const count=(pendingBatch()||queue.some(c=>c.kind==='DAILY_RATE')?1:0)+queue.filter(c=>c.kind!=='DAILY_RATE').length;
 return head('OPERATOR OVERVIEW','Compliance dashboard.','See where wages fall below the approved minimum and what needs attention.')+
 `<div class="section-heading"><div><span class="eyebrow">EMPLOYEE RESULTS · ${esc(state.retained_results_date||day)}</span><h2>${state.retained_results_date?'Last approved results':day===utcToday()?"Today's results":'Results for the selected date'} · ${state.summary.total} workers</h2></div><button class="link-button" data-dashboard-all>See all employees →</button></div>`+
 retainedNotice()+metrics()+
 (count?`<section class="panel"><div class="panel-head"><div><h2>${count} pending ${count===1?'inspection':'inspections'}</h2><p>Review the saved evidence before updated rules change employee results.</p></div><button class="primary small" data-view="review">Inspect updates →</button></div></section>`:'')+dashboardDetail();
}
function dashboardDetail(){
 const rows=state.results;
 const locations=[...new Set(rows.map(r=>r.work_jurisdiction||'Location missing'))];
 const groups=locations.map(location=>{const workers=rows.filter(r=>(r.work_jurisdiction||'Location missing')===location),below=workers.filter(r=>r.decision_state==='NON_COMPLIANT').length,meets=workers.filter(r=>r.decision_state==='COMPLIANT').length,review=workers.length-below-meets;
  return `<div class="location-result"><div class="location-result-title"><h3>${esc(location)}</h3><span>${workers.length} employees</span></div><svg class="result-distribution" viewBox="0 0 100 11" preserveAspectRatio="none" role="img" aria-label="${esc(location)}: ${below} below minimum, ${meets} meet minimum, ${review} need review">${[[below,'below',0],[meets,'meets',below],[review,'unresolved',below+meets]].filter(([n])=>n).map(([n,key,start])=>`<rect class="${key}" x="${start/workers.length*100}" width="${n/workers.length*100}" height="11"></rect>`).join('')}</svg><div class="location-result-counts"><span><i class="legend-dot below"></i><b>${below}</b> below</span><span><i class="legend-dot meets"></i><b>${meets}</b> meet</span><span><i class="legend-dot unresolved"></i><b>${review}</b> review</span></div></div>`;
 }).join('');
 const unresolved=rows.filter(r=>!['COMPLIANT','NON_COMPLIANT'].includes(r.decision_state));
 const reasonCounts=new Map();unresolved.forEach(r=>{const label=decisionReason(r)||'Missing or unresolved data';reasonCounts.set(label,(reasonCounts.get(label)||0)+1);});
 const gaps=rows.filter(r=>r.decision_state==='NON_COMPLIANT'&&r.actual_hourly_wage!=null&&r.controlling_minimum_wage!=null).sort((a,b)=>(Number(b.controlling_minimum_wage)-Number(b.actual_hourly_wage))-(Number(a.controlling_minimum_wage)-Number(a.actual_hourly_wage))||a.employee_id.localeCompare(b.employee_id));
 const cases=gaps.slice(0,4).map(r=>`<tr><td><button class="link-button" data-dashboard-employee="${esc(r.employee_id)}">${esc(r.employee_id)}</button><small>${esc(r.work_jurisdiction)}</small></td><td>${fmt(r.actual_hourly_wage)}</td><td>${fmt(r.controlling_minimum_wage)}</td><td><strong class="wage-gap">${fmt(Number(r.controlling_minimum_wage)-Number(r.actual_hourly_wage))}</strong></td></tr>`).join('');
 return `<div class="dashboard-grid"><section class="panel dashboard-panel"><div class="panel-head"><div><h2>Results by work location</h2><p>${state.retained_results_date?'Saved results':'Employee results'} · ${esc(state.retained_results_date||day)}</p></div></div><div class="panel-body">${groups||'<p>No employee results yet.</p>'}</div><div class="dashboard-followup"><div><h3>${unresolved.length?`${unresolved.length} employee cases need review`:'Employee reviews are clear'}</h3>${unresolved.length?`<ul class="reason-summary">${[...reasonCounts].map(([reason,n])=>`<li><span>${esc(reason)}</span><b>${n}</b></li>`).join('')}</ul>`:'<p>All supplied employee results have a decision.</p>'}</div>${unresolved.length?'<button class="link-button" data-dashboard-review>View review cases →</button>':''}</div></section><section class="panel dashboard-panel"><div class="panel-head"><div><h2>Wages to investigate</h2><p>${state.retained_results_date?'From saved results · ':''}Largest hourly gaps · AST/hour</p></div><span class="chip">${gaps.length} below minimum</span></div>${cases?`<div class="table-scroll"><table class="priority-table"><thead><tr><th>Employee</th><th>Wage</th><th>Floor</th><th>Gap / hr</th></tr></thead><tbody>${cases}</tbody></table></div>`:'<p class="empty">No confirmed below-minimum results in this view.</p>'}<div class="dashboard-panel-foot"><span>Recorded hourly pay only; salary estimates excluded.</span><button class="link-button" data-dashboard-all>All employee results →</button></div></section></div>`;
}
function reviewCard(c){return `<article class="review-card"><div class="review-top"><div><h2>${esc(c.source_rule_id)}</h2><p>${esc(c.jurisdiction)} · ${esc(pretty(c.kind))} · version ${esc(short(c.id))}</p></div>${chip(c.state)}</div><div class="rule-line">${c.amount?`<span class="rule-amount">${fmt(c.amount)}</span><span class="muted">AST / hour</span><span class="chip">Effective ${esc(c.effective_from)}</span>`:`<span class="chip">${esc(publicationType(c))}</span>`}</div><p class="lead">${esc(reviewSummary(c))}</p><div class="actions"><button class="${c.state==='REVIEW_REQUIRED'?'primary':'secondary'} small" data-rule="${esc(c.id)}">${c.state==='REVIEW_REQUIRED'&&c.amount?'Preview impact & review':'Inspect evidence'} ↗</button>${c.effective_from>day?'<span class="chip amber">Future-effective · not active today</span>':''}${c.effective_to&&c.effective_to<=day?'<span class="chip">Historical · expired</span>':''}</div></article>`;}
function archiveGroup(c){
 if(c.classification==='RATE_REVIEW'){
  if(c.effective_from>day)return 'future';
  if(c.effective_to&&c.effective_to<=day)return 'past';
  if(c.state==='APPROVED')return 'current';
 }
 if(c.kind==='CORRECTION'||c.kind==='GUIDANCE')return 'interpretation';
 if(c.kind==='PROPOSAL'||c.kind==='NEWS'||c.classification==='NOT_LAW'||c.classification==='IRRELEVANT')return 'nonrate';
 return 'other';
}
function publicationRegister(){
 const definitions=[['current','Current publications'],['future','Future rates'],['interpretation','Interpretations'],['nonrate','Other information'],['past','History']];
 const items=state.candidates;
 const inGroup=(c,key)=>key==='current'?archiveGroup(c)!=='past':archiveGroup(c)===key;
 const selected=items.filter(c=>inGroup(c,publicationFilter)).sort((a,b)=>{
  const order={other:0,current:1,future:2,interpretation:3,nonrate:4,past:5};
  return order[archiveGroup(a)]-order[archiveGroup(b)]||(b.effective_from||b.discovered_at||'').localeCompare(a.effective_from||a.discovered_at||'')||a.jurisdiction.localeCompare(b.jurisdiction);
 });
 const tabs=definitions.map(([key,label])=>`<button class="publication-filter" data-publication-filter="${key}" aria-pressed="${publicationFilter===key}">${label}<span>${items.filter(c=>inGroup(c,key)).length}</span></button>`).join('');
 const records=selected.map(c=>{
  const group=archiveGroup(c),rate=c.classification==='RATE_REVIEW'&&c.amount;
  const title=({DAILY_RATE:'Daily minimum wage',FINAL_NOTICE:group==='future'?'Future wage notice':'Minimum wage notice',CORRECTION:'Coverage correction',GUIDANCE:'Wage interpretation',PROPOSAL:'Proposed wage rule',NEWS:'Operational news'})[c.kind]||pretty(c.kind);
  const effect=rate?`<strong>${fmt(c.amount)} AST/hour</strong><small>${group==='future'?'Starts':group==='past'?'Historical date':'Effective'} ${esc(c.effective_from)}</small>`:c.kind==='CORRECTION'?esc(c.source_rule_id==='AFWA-2026-0038'?'Employer threshold: 24 → 25':'Scope correction'):c.kind==='GUIDANCE'?esc(c.source_rule_id==='BDL-2026-0121'?'Higher federal or state rate':c.source_rule_id==='BDL-2026-0108'?'Physical work location determines scope':'Interpretation; no new rate'):c.kind==='PROPOSAL'?'Not an active wage rule':c.kind==='NEWS'?'No minimum-wage effect':esc(c.reason||'Needs interpretation');
  const status=c.state==='REJECTED'?'Rejected':c.policy_applied?'Applied in logic':group==='past'?'Historical':c.state==='ACKNOWLEDGED'?'Acknowledged':c.kind==='PROPOSAL'?'Not law':c.kind==='NEWS'?'Evidence only':group==='future'?(c.state==='APPROVED'?'Approved · future':'Pending approval'):c.state==='APPROVED'?'Approved':'Needs review';
  const tone=c.state==='REJECTED'||c.policy_applied||group==='past'||['PROPOSAL','NEWS'].includes(c.kind)?'NEUTRAL':c.state;
  return `<tr><td><strong>${esc(title)}</strong><small>${esc(c.jurisdiction)} · ${esc(c.source_rule_id)}</small></td><td>${effect}</td><td>${chip(tone,status)}</td><td><button class="link-button" data-rule="${esc(c.id)}" aria-label="Inspect ${esc(c.source_rule_id)} ${esc(c.effective_from||c.kind)}">Inspect ↗</button></td></tr>`;
 }).join('');
 return `<section class="panel publication-register"><div class="panel-head"><div><h2>Publication register</h2><p>Approved rules, upcoming changes and supporting information.</p></div><span class="register-total">${items.length} saved records</span></div><div class="publication-filters" aria-label="Filter publications">${tabs}</div><div class="table-scroll">${records?`<table class="publication-table"><thead><tr><th>Publication</th><th>Wage effect</th><th>Status</th><th></th></tr></thead><tbody>${records}</tbody></table>`:'<p class="empty">No publications in this category.</p>'}</div><div class="register-foot">${selected.length} records shown · Future rates require approval and their start date.</div></section>`;
}
function reviews(){
 const {blocking}=currentReviewQueue();
 const dailyBatch=pendingBatch();const separate=mode==='live'?blocking.filter(c=>c.kind!=='DAILY_RATE'):blocking;
 const pending=!!dailyBatch||separate.length||blocking.some(c=>c.kind==='DAILY_RATE');
 const today=(dailyBatch?batchCard(dailyBatch):'')+separate.map(reviewCard).join('')+(!dailyBatch&&mode==='live'&&blocking.some(c=>c.kind==='DAILY_RATE')?'<div class="alert-box">Check both websites to prepare a complete federal + state inspection.</div>':'');
 return head('RULE REVIEW','Rules and publications.','Review today’s updates, prepare for future changes and inspect source evidence.')+(knownAt?'<div class="alert-box">Historical knowledge view is read-only. Return to current knowledge to review rules.</div>':'')+(pending?`<h2 class="review-section-title">Needs review today</h2>${today}`:'<div class="review-clear"><span class="review-clear-icon" aria-hidden="true">✓</span><div><strong>No source approvals pending for today</strong><p>Future notices and supporting publications are listed below.</p></div></div>')+publicationRegister();
}
function displayedEmployees(){return historicalResults?historicalResults.results:state.results;}
document.addEventListener('click',async event=>{
 const b=event.target.closest('button');if(!b)return;
 try{
  if(b.dataset.publicationFilter){publicationFilter=b.dataset.publicationFilter;await render();}
  if(b.dataset.dashboardEmployee){historicalResults=null;selectedHistoryRule='';updateExportLink();employeeDialog(b.dataset.dashboardEmployee);}
  if(b.hasAttribute('data-dashboard-all')){historicalResults=null;selectedHistoryRule='';employeeFilter='ACTUAL';employeeSearch='';view='decisions';await render();window.scrollTo(0,0);}
  if(b.hasAttribute('data-dashboard-review')){historicalResults=null;selectedHistoryRule='';employeeFilter='REVIEW_REQUIRED';employeeSearch='';view='decisions';await render();window.scrollTo(0,0);}
 }catch(e){error(e);}
});
function resultHistoryPicker(){const sets=state.saved_result_sets||[];return `<div class="toolbar"><label for="rule-history">Results from</label><select id="rule-history"><option value="">Latest results</option>${sets.map(b=>`<option value="${esc(b.id)}" ${selectedHistoryRule===b.id?'selected':''}>${esc(b.evaluation_date)} · Federal ${fmt(b.rules.find(r=>r.jurisdiction==='Asteria')?.amount)} / State ${fmt(b.rules.find(r=>r.jurisdiction==='Bellwether')?.amount)} · ${b.legacy?'Earlier approved results':(b.result_label||'Approved inspection')+' '+esc(short(b.parent_batch_id||b.id))}</option>`).join('')}</select></div>${historicalResults?`<div class="alert-box"><b>${esc(historicalResults.result_label||'Saved combined results')} · ${esc(historicalResults.evaluation_date)}</b><p>${historicalResults.results.length} employees · Federal and state rules together.${historicalResults.legacy?' Earlier separate approvals; not a retroactive joint approval.':' Approved by '+esc(historicalResults.actor)+'.'}</p>${inspectionDetails(historicalResults)}</div>`:retainedNotice()}`;}
function decisions(){return head('EMPLOYEE DECISIONS','Employee results.','See recorded wages, the applicable floor and the result.')+resultHistoryPicker()+`<div class="toolbar"><label class="sr-only" for="employee-search">Search employee</label><input id="employee-search" placeholder="Search employee or work location"><label class="sr-only" for="status-filter">Filter decision</label><select id="status-filter"><option value="ACTUAL">Actual results</option><option value="ALL">All decisions including salary estimates</option><option value="APPROVED">Approved results</option><option value="REVIEW_REQUIRED">Review required</option></select><a class="secondary small" href="${employeeExportUrl()}">↓ Export all JSON</a><span class="status-count" id="result-count"></span></div><p class="lead" id="decision-view-note"></p><section class="panel" id="employee-table"></section>`;}

async function lab(){if(!labCache)labCache=await api('/api/lab');const l=labCache;const main=dummyForm(await api('/api/dummy-tests'));return head('SCENARIO LAB','Test without changing live results.','Enter hypothetical rates and see their effect. Every test is saved as a dummy.')+main+`<details class="panel lab-checks"><summary>Automated checks · ${l.golden_cases.filter(c=>c.pass).length}/${l.golden_cases.length} scenarios passed</summary><div class="panel-body"><div class="metrics">${metric('Curated safety scenarios',`${l.golden_cases.filter(c=>c.pass).length} / ${l.golden_cases.length}`,'Includes ambiguity, outage and correction','green')}${metric('Independent arithmetic checks',l.oracle.passed.toLocaleString(),'Exact fractions · fixed reproducible seed','green')}${metric('Deliberate bugs detected',`${l.mutations.filter(m=>m.detected).length} / ${l.mutations.length}`,'Actual mutations of the engine','green')}${metric('Instruction-like source fixture',l.injection_fixture_quarantined?'Quarantined':'Failed','Triage signal; not a complete defense','green')}</div><div class="alert-box">Synthetic cases test the deterministic workflow; they do not establish universal regulatory coverage.</div><div class="lab-grid">${l.golden_cases.map(c=>`<article class="lab-case"><span class="pass">${c.pass?'✓ PASS':'FAILED'}</span><h3>${esc(c.title)}</h3><p>Expected: ${esc(pretty(c.expected))}</p><p>Observed: ${esc(pretty(c.actual))}</p><details><summary>Why this result</summary><p>${esc(c.explanation?.join(' ')||c.error)}</p></details></article>`).join('')}</div><section class="panel"><div class="panel-head"><h2>Would our tests catch a plausible coding mistake?</h2></div><div class="panel-body">${l.mutations.map(m=>`<p><span class="pass">${m.detected?'CAUGHT':'MISSED'}</span> ${esc(pretty(m.mutation.replaceAll('-','_')))} <small class="muted">— ${esc(m.caught_by.join(', '))}</small></p>`).join('')}<p class="lead">${esc(l.oracle.scope)}</p></div></section></div></details>`;}
async function render(){updateExportLink();renderSourceBar();const draftForm=$('#dummy-form');const active=document.activeElement;const focus=draftForm?.contains(active)?{name:active.name,start:active.selectionStart,end:active.selectionEnd}:null;if(draftForm)dummyDraft=Object.fromEntries(new FormData(draftForm));const opened=new Set([...document.querySelectorAll('#content details[open]')].map(d=>d.querySelector('summary')?.textContent));if($('#employee-search'))employeeSearch=$('#employee-search').value;if($('#status-filter'))employeeFilter=$('#status-filter').value;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#content').innerHTML=view==='overview'?overview():view==='review'?reviews():view==='decisions'?decisions():await lab();document.querySelectorAll('#content details').forEach(d=>{if(opened.has(d.querySelector('summary')?.textContent))d.open=true;});if(view==='lab'&&dummyDraft){const form=$('#dummy-form');for(const [name,value] of Object.entries(dummyDraft))if(form?.elements[name])form.elements[name].value=value;if(focus?.name&&form?.elements[focus.name]){const field=form.elements[focus.name];field.focus({preventScroll:true});if(focus.start!==null&&field.setSelectionRange)try{field.setSelectionRange(focus.start,focus.end);}catch{}}}if(view==='decisions'){$('#employee-search').value=employeeSearch;$('#status-filter').value=employeeFilter;filterResults();}}
async function load(){try{$('#error').hidden=true;day=utcToday();state=await api('/api/state');const blockers=currentReviewQueue().blocking;const reviewCount=(pendingBatch()||blockers.some(c=>c.kind==='DAILY_RATE')?1:0)+blockers.filter(c=>c.kind!=='DAILY_RATE').length;$('#pending-count').textContent=reviewCount;$('#pending-count').title='Source items affecting today’s decisions';await render();scheduleMonitorRefresh();}catch(e){error(e);scheduleMonitorRefresh();}}
function reviewGuidance(c){
 if(c.source_rule_id!=='AFWA-2026-0038')return '';
 return `<div class="review-guidance"><strong>Coverage needs a decision</strong><p>The threshold changed from 24 to 25 employees. The file says “Covered” but lacks employer headcount. Acknowledge only if you accept that field as an upstream coverage decision; otherwise leave this pending.</p></div>`;
}
function rateChangePanel(report,c){
 if(!report)return '';
 const old=report.previous_rate,newRate=report.new_rate;
 if(!old)return `<section class="rate-change"><span class="eyebrow">RATE HISTORY</span><h2>Before/after comparison unavailable</h2><p>${esc(report.basis)}</p></section>`;
 const delta=Number(report.rate_delta),deltaLabel=(delta>0?'+':'')+fmt(delta);
 const changed=report.rows.filter(r=>r.changed);
 const url='/api/rate-change?'+query({id:c.id,...(c.state==='REVIEW_REQUIRED'&&c.effective_from===old.effective_from?{supersedes:old.id}:{}) ,format:'csv'});
 const workerRows=changed.map(r=>`<tr><td><strong>${esc(r.employee_id)}</strong><small>${esc(r.work_state)}</small></td><td>${fmt(r.recorded_hourly_wage)}</td><td>${fmt(r.previous_floor)} → ${fmt(r.new_floor)}</td><td>${fmt(r.previous_weekly_estimate)} → ${fmt(r.new_weekly_estimate)}</td><td>${chip(r.new_decision)}</td></tr>`).join('');
 return `<section class="rate-change"><div class="rate-change-head"><div><span class="eyebrow">RATE CHANGE · ${esc(c.jurisdiction)}</span><h2>${fmt(old.amount)} → ${fmt(newRate.amount)} AST/hour <span class="rate-delta">(${esc(deltaLabel)})</span></h2><p>Previous: ${esc(old.effective_from)} · ${esc(old.source_rule_id)}. New: ${esc(newRate.effective_from)} · ${esc(newRate.source_rule_id)}.</p></div>${chip(c.state,c.state==='APPROVED'?'Approved rule':'Proposed rule')}</div><div class="rate-change-stats"><div><strong>${report.changed_hourly}</strong><span>hourly workers with changed results</span></div><div><strong>${report.newly_below}</strong><span>newly below floor</span></div><div><strong>${report.no_longer_below}</strong><span>no longer below floor</span></div><div><strong>${report.potentially_affected_unresolved}</strong><span>changed reference floor; wage review needed</span></div></div><p class="rate-change-note">${esc(report.basis)} ${report.unresolved_workers} in-scope workers lack a final hourly comparison; the CSV marks which of their reference floors changed.</p><div class="rate-change-actions"><details><summary>View ${changed.length} changed hourly worker${changed.length===1?'':'s'}</summary>${changed.length?`<div class="table-scroll"><table><thead><tr><th>Employee</th><th>Recorded wage</th><th>Floor: old → new</th><th>Weekly gap: old → new</th><th>New status</th></tr></thead><tbody>${workerRows}</tbody></table></div>`:'<p>No supported hourly result changed. The rate may still matter outside this dataset.</p>'}</details><a href="${esc(url)}" download>↓ Export all ${report.in_jurisdiction} in-scope workers (CSV)</a></div><p class="rate-change-note">Estimated weekly gap change for supported hourly workers: ${esc((Number(report.weekly_estimate_delta)>0?'+':'')+fmt(report.weekly_estimate_delta))} AST. This uses scheduled hours and is not a payroll liability total.</p></section>`;
}
async function ruleDialog(id){const c=state.candidates.find(c=>c.id===id);if(!c)return;const pair=pendingBatch();if(mode==='live'&&pair?.rules.some(r=>r.id===id)){return batchDialog(pair.id);}const replacements=state.candidates.filter(r=>r.state==='APPROVED'&&r.id!==c.id&&r.jurisdiction===c.jurisdiction&&r.effective_from===c.effective_from&&!state.candidates.some(x=>x.supersedes===r.id&&x.state==='APPROVED'));const replacement=replacements.length===1?replacements[0].id:'';let preview=null,transition=null;if(c.classification==='RATE_REVIEW'){transition=await api('/api/rate-change',{id,supersedes:replacement});if(transition.previous_rate?.effective_from===c.effective_from)preview=await api('/api/impact',{id,date:c.effective_from>day?c.effective_from:day,supersedes:replacement});}
 const rate=c.classification==='RATE_REVIEW';
 const impact=preview?(preview.changes.length?`${preview.changes.length} employee results would change; below-minimum count ${preview.before.counts.NON_COMPLIANT||0} → ${preview.after.counts.NON_COMPLIANT||0}.`:'No employee decision changes in this isolated preview. Other pending rules may still affect the final result.'):'';
 const sourceLinks=`<div class="review-links"><a href="${esc(c.source_url)}" target="_blank" rel="noopener noreferrer">Open official page ↗</a><a href="/api/snapshot?${query({id:c.snapshot_id})}" target="_blank" rel="noopener">Open saved copy ↗</a></div>`;
 const comparisonNote=c.state==='APPROVED'?'Approved. This comparison isolates the rate change.':c.state==='REJECTED'?'Rejected. This rate is not applied to employee results.':'Final results require approval and an applicable effective date.';
 const facts=rate?`<section class="review-brief"><h2>${transition?.previous_rate?`${fmt(transition.previous_rate.amount)} → `:''}${fmt(c.amount)} <small>AST / hour</small></h2><p>${esc(c.jurisdiction)} · Effective ${esc(c.effective_from)}</p>${transition?.previous_rate?`<p><b>${transition.changed_hourly} hourly workers</b> with a change in the rate-only comparison. <span class="muted">${esc(comparisonNote)}</span></p>`:'<p class="muted">No resolved previous rate for comparison.</p>'}</section>`:`<p class="review-summary">${esc(reviewSummary(c))}</p>`;

 const replacementField=replacements.length?`<label>Replaces an approved rate?<select name="supersedes"><option value="">No replacement</option>${replacements.map(r=>`<option value="${esc(r.id)}" ${r.id===replacement?'selected':''}>${fmt(r.amount)} AST · ${esc(short(r.id))}</option>`).join('')}</select></label>`:'';
 const form=c.state==='REVIEW_REQUIRED'&&!c.policy_applied&&!knownAt&&!(mode==='live'&&c.kind==='DAILY_RATE')?`<form id="review-form" class="review-form"><input type="hidden" name="id" value="${esc(id)}"><div class="form-row"><label>Your name<input name="actor" required value="${esc(reviewerName)}" placeholder="Your name" autocomplete="name"></label>${replacementField}</div><label class="review-check"><input type="checkbox" name="checked" required><span>I checked the saved source and compared it with the facts above.</span></label><details class="review-optional-note"><summary>Add a note (optional unless rejecting)</summary><label>Note <small>${rate?'Optional for approval · required if rejecting':'Optional for acknowledgment · required if rejecting'}</small><textarea name="note" rows="2" placeholder="Add an exception or explain a rejection"></textarea></label></details><p id="review-note-error" class="check-error" role="alert" hidden></p><div class="actions">${rate?'<button class="primary" name="decision" value="APPROVED">Approve rule</button>':c.classification!=='SECURITY_REVIEW'&&c.kind!=='UNKNOWN'?'<button class="primary" name="decision" value="ACKNOWLEDGED">Acknowledge</button>':''}<button class="secondary" name="decision" value="REJECTED">Reject</button></div><p class="review-footnote">Your name, checked facts and decision are saved in the audit record. </p></form>`:'';
 modal(`<div class="review-title"><div><span class="eyebrow">${esc(c.jurisdiction)} · ${esc(c.kind)}</span><h1>${esc(c.source_rule_id)}</h1></div>${c.policy_applied?chip('ACKNOWLEDGED','Handled by existing logic'):chip(c.state)}</div>${facts}${sourceLinks}${reviewGuidance(c)}${form}<details class="review-details"><summary>Evidence, affected workers &amp; additional details</summary>${rate?`<p class="review-summary">${esc(reviewSummary(c))}</p>`:''}${rateChangePanel(transition,c)}<div class="evidence">${esc(c.evidence)}</div><p class="muted">Published: ${esc(c.publication_date||'Not separately provided')} · Effective: ${esc(c.effective_from||'Needs interpretation')}</p>${preview?`<p class="lead">${esc(preview.basis)} Evaluation date: ${esc(preview.evaluation_date)}.</p><div class="impact-grid"><div>In jurisdiction<strong>${preview.affected_employees}</strong>${preview.unaffected_employees} outside</div><div>Below minimum<strong>${preview.before.counts.NON_COMPLIANT||0} → ${preview.after.counts.NON_COMPLIANT||0}</strong>Supported hourly cases</div><div>Weekly estimate change<strong>${fmt(preview.weekly_shortfall_delta)}</strong>AST · ${preview.after.employees_with_weekly_estimate} supported estimates</div></div><details><summary>Inspect ${preview.changes.length} changed results</summary><pre>${esc(JSON.stringify(preview.changes,null,2))}</pre></details>`:''}<details><summary>Field evidence and source version</summary><pre>${esc(JSON.stringify({field_evidence:c.field_evidence,version:c.id,source_url:c.source_url,discovered_at:c.discovered_at,reviewed_at:c.reviewed_at,reviewer:c.actor,reason:c.review_reason},null,2))}</pre></details></details>`);
}
function reviewReason(c,decision,note){
 if(decision==='REJECTED')return note;
 const checked=c.classification==='RATE_REVIEW'?`Checked saved source ${c.source_rule_id}: ${c.amount} ${c.currency}/${c.unit}, effective ${c.effective_from}, coverage ${c.coverage}. ${c.reason}`:c.source_rule_id==='AFWA-2026-0038'?'Checked the source; accepted the supplied Covered field as an upstream coverage decision although employer headcount is missing.':`Checked saved source ${c.source_rule_id}; classification ${c.classification}. ${c.reason}`;
 return note?checked+' Reviewer note: '+note:checked;
}
function reviewContext(r){if(['COMPLIANT','NON_COMPLIANT'].includes(r.decision_state))return '';const c=r.analysis_context||{},e=r.employee_input||{};const salary=c.indicative_salary_hourly!==null&&c.indicative_salary_hourly!==undefined?`<p><b>Salary:</b> ${fmt(e.annual_salary_ast)} AST/year · ${esc(e.scheduled_hours_per_week)} scheduled hours/week → about <b>${fmt(c.indicative_salary_hourly)} AST/hour</b>.</p><p>${esc(c.salary_assumption)}</p>`:'';const reference=c.approved_reference_floor!==null&&c.approved_reference_floor!==undefined?`<p><b>Approved floor for this location:</b> ${fmt(c.approved_reference_floor)} AST/hour (${esc(c.approved_reference_jurisdiction)}). ${esc(c.approved_reference_meaning)}</p>`:'';const pending=(c.pending_rate_candidates||[]).length?`<p><b>Pending rate proposals:</b> ${c.pending_rate_candidates.map(x=>`${fmt(x.amount)} AST/hour in ${esc(x.jurisdiction)}, effective ${esc(x.effective_from)}`).join('; ')}.</p>`:'';const gap=c.indicative_hourly_gap_to_reference!==null&&c.indicative_hourly_gap_to_reference!==undefined?`<p><b>Illustrative salary gap to approved floor:</b> ${fmt(c.indicative_hourly_gap_to_reference)} AST/hour; ${fmt(c.indicative_weekly_gap_to_reference)} AST/week using scheduled hours. This is a triage estimate, not an underpayment finding.</p>`:'';const recorded=Number(c.recorded_hourly_gap_to_reference)>0&&r.decision_state==='REVIEW_REQUIRED'?`<p><b>Recorded wage below currently approved floor:</b> ${fmt(c.recorded_hourly_gap_to_reference)} AST/hour; ${fmt(c.recorded_weekly_gap_to_reference)} AST/week using scheduled hours. Investigate now; a pending correction still prevents a final decision.</p>`:'';return salary||reference||pending||recorded?`<h2>Review context</h2><div class="alert-box">${salary}${reference}${pending}${gap}${recorded}</div>`:'';}
function salaryReview(r){const c=r.analysis_context||{},e=r.employee_input||{};const proxy=c.indicative_salary_hourly!==null&&c.indicative_salary_hourly!==undefined;const reference=c.approved_reference_floor!==null&&c.approved_reference_floor!==undefined;const gap=reference&&Number(c.indicative_hourly_gap_to_reference)>0;const needs=c.salary_review_requirements||[];return `<section class="salary-review"><span class="eyebrow">ILLUSTRATION ONLY · NO FINAL WAGE DECISION</span><h2>Annual salary needs a separate review</h2><div class="salary-facts"><div>Annual salary<strong>${fmt(e.annual_salary_ast)}</strong>AST / year</div><div>Illustrative hourly amount<strong>${proxy?'~'+fmt(c.indicative_salary_hourly):'—'}</strong>AST / hour · scheduled-hours assumption</div><div>Approved floor reference<strong>${reference?fmt(c.approved_reference_floor):'—'}</strong>${reference?`${esc(c.approved_reference_jurisdiction)} · may change`:'Awaiting applicable approved rules'}</div></div><p>${proxy?`Estimate: ${fmt(e.annual_salary_ast)} ÷ (52 × ${esc(e.scheduled_hours_per_week)} scheduled hours) ≈ ${fmt(c.indicative_salary_hourly)} AST/hour.`:'A usable salary or scheduled-hours value is missing, so even an illustration cannot be calculated.'} ${gap?`Illustrative gap: ${fmt(c.indicative_hourly_gap_to_reference)} AST/hour, or ${fmt(c.indicative_weekly_gap_to_reference)} AST/week. This is a review priority, not unpaid wages.`:''}</p>${(c.pending_rate_candidates||[]).length?`<p>Pending rate proposals may change the reference floor.</p>`:''}<h3>Before a final decision, obtain:</h3><ul>${needs.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`;}
function employeeDialog(id){const r=displayedEmployees().find(r=>r.employee_id===id);if(!r)return;const salary=r.employee_input?.pay_basis==='Annual Salary';const main=salary?salaryReview(r):`<div class="impact-grid"><div>Actual hourly wage<strong>${fmt(r.actual_hourly_wage)}</strong>AST / hour</div><div>Controlling minimum<strong>${fmt(r.controlling_minimum_wage)}</strong>${esc(r.controlling_jurisdiction||'Unresolved')}</div><div>Weekly shortfall estimate<strong>${fmt(r.estimated_weekly_underpayment)}</strong>AST · scheduled hours only</div></div>${reviewContext(r)}`;modal(`<span class="eyebrow">DECISION RECEIPT / ${esc(r.work_jurisdiction)}</span><h1>${esc(r.employee_id)}</h1><p>Result date: ${esc(r.evaluation_date)}${!historicalResults&&state.retained_results_date?' · Saved result':''}</p>${currentEmployeeIssue(id)}${chip(r.decision_state)}${main}<h2>Why this decision</h2><ol class="receipt-steps">${r.explanation.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="alert-box"><b>Next action:</b> ${esc(r.next_action)}</div>${r.supporting_evidence?`<h2>Controlling source evidence</h2><div class="evidence">${esc(r.supporting_evidence)}</div>`:''}<div class="toolbar"><a class="primary" href="/api/receipt?${query({id:r.evaluation_id})}">↓ Download decision receipt</a><button class="secondary" data-verify="${esc(r.evaluation_id)}">Verify replay now</button></div><p class="mono">Evaluation ${esc(r.evaluation_id)}</p><details><summary>Employee inputs, candidate rules and audit metadata</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details><div id="receipt-status" role="status"></div>`);}
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;try{if(b.dataset.view){view=b.dataset.view;await render();window.scrollTo(0,0);}if(b.dataset.employee)employeeDialog(b.dataset.employee);if(b.dataset.rule)await ruleDialog(b.dataset.rule);if(b.dataset.batch)await batchDialog(b.dataset.batch);if(b.dataset.verify){const r=await api('/api/receipt',{id:b.dataset.verify,verify:'1'});$('#receipt-status').textContent=r.valid?'Verified: source hashes, rule binding, engine and decision replay agree.':'Verification failed: '+r.errors.join('; ');}if(b.dataset.action==='fetch'){b.disabled=true;state.monitor=await post('/api/fetch');await render();scheduleMonitorRefresh();}if(b.dataset.action==='monitor-start'){b.disabled=true;await post('/api/monitor/start');await load();toast('Automatic checks started. Checking both sites now, then every 15 minutes.');}if(b.dataset.action==='monitor-stop'){b.disabled=true;await post('/api/monitor/stop');await load();toast('Automatic checks stopped.');}}catch(e){error(e);toast(e.message);b.disabled=false;}});
// A form control named "id" shadows form.id; use the actual attribute.
document.addEventListener('submit',async event=>{if(event.target.getAttribute('id')==='review-form'){event.preventDefault();const form=event.target,button=event.submitter;try{const data=Object.fromEntries(new FormData(form));const candidate=state.candidates.find(c=>c.id===data.id);const note=(data.note||'').trim();if(!candidate)throw Error('Source item no longer available');if(button.value==='REJECTED'&&note.length<25){const error=$('#review-note-error');error.textContent='Please explain the rejection in at least 25 characters.';error.hidden=false;form.elements.note.closest('details').open=true;form.elements.note.focus();return;}data.decision=button.value;data.reason=reviewReason(candidate,data.decision,note);delete data.checked;delete data.note;button.disabled=true;await post('/api/review',data);reviewerName=data.actor.trim();$('#detail-dialog').close();await load();toast(failedReevaluations(state.monitor).length?'Review recorded. Some re-evaluations need retry.':'Review recorded. Affected historical decisions re-evaluated.');}catch(e){error(e);toast(e.message);button.disabled=false;}}});
function filterResults(){
 if(view!=='decisions')return;
 const text=($('#employee-search')?.value||'').toLowerCase(),status=$('#status-filter')?.value||'ACTUAL';
 employeeSearch=$('#employee-search')?.value||'';employeeFilter=status;
 const decided=r=>['COMPLIANT','NON_COMPLIANT'].includes(r.decision_state);
 const matches=(r,category)=>category==='ALL'?true:category==='ACTUAL'?r.employee_input?.pay_basis==='Hourly':category==='APPROVED'?decided(r):!decided(r);
 const searched=displayedEmployees().filter(r=>(r.employee_id+' '+r.work_jurisdiction).toLowerCase().includes(text));
 const labels={ACTUAL:'Actual results',ALL:'All decisions including salary estimates',APPROVED:'Approved results',REVIEW_REQUIRED:'Review required'};
 for(const option of $('#status-filter').options){const count=searched.filter(r=>matches(r,option.value)).length;option.textContent=`${labels[option.value]} · ${count} ${count===1?'entry':'entries'}`;}
 const rows=searched.filter(r=>matches(r,status));
 $('#employee-table').innerHTML=rows.length?table(rows,false,status==='ALL'):'<p class="empty">No employees match this view.</p>';
 $('#result-count').textContent=`Showing ${rows.length} ${rows.length===1?'entry':'entries'}${text?' matching your search':''}`;
 $('#decision-view-note').textContent=({ACTUAL:'Hourly-pay records only. Salary estimates are excluded.',ALL:'All employees. ~ amounts are salary estimates, not actual hourly pay or final compliance results.',APPROVED:'Completed results using approved rules: both meets minimum and below minimum.',REVIEW_REQUIRED:'Employees awaiting source review, salary policy or missing data.'})[status];
}

document.addEventListener('input',e=>{if(e.target.id==='employee-search')filterResults();});document.addEventListener('change',e=>{if(e.target.id==='status-filter')filterResults();});

$('#close-dialog').addEventListener('click',()=>$('#detail-dialog').close());
async function refreshLive(){if(mode!=='live')return;await load();}
setInterval(refreshLive,60000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshLive();});
load();

document.addEventListener('change',async e=>{if(e.target.id!=='rule-history')return;const id=e.target.value;e.target.disabled=true;try{const saved=id?await api('/api/saved-results',{id}):null;historicalResults=saved;selectedHistoryRule=id;await render();}catch(err){error(err);e.target.disabled=false;e.target.value=selectedHistoryRule;}});

function pendingBatch(){return mode==='live'?(state.review_batches||[]).find(b=>b.state==='REVIEW_REQUIRED'&&b.evaluation_date===day):null;}
function batchCard(b){return `<article class="review-card"><h2>Federal + state update · ${esc(b.evaluation_date)}</h2><p>${b.rules.map(r=>`${esc(r.jurisdiction)}: ${fmt(r.amount)} AST/hour`).join(' · ')}</p><button class="primary" data-batch="${esc(b.id)}">Inspect both rates →</button></article>`;}
function combinedImpactPanel(report){if(!report.comparison_available)return `<p>${esc(report.basis)}</p>`;const rows=report.rows.filter(r=>r.changed);return `<p>${report.changed_hourly} hourly workers with changed results · ${report.newly_below} newly below minimum · ${report.no_longer_below} no longer below minimum.</p><p class="muted">${esc(report.basis)} ${report.unresolved_workers} employee cases still need separate review.</p><details><summary>View ${rows.length} changed workers</summary><div class="table-scroll"><table><thead><tr><th>Employee</th><th>Previous floor</th><th>Proposed floor</th><th>Proposed result</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.employee_id)}<small>${esc(r.work_jurisdiction)}</small></td><td>${fmt(r.previous_floor)}</td><td>${fmt(r.new_floor)}</td><td>${chip(r.new_decision)}</td></tr>`).join('')}</tbody></table></div></details><p><a href="/api/batch-impact?${query({id:report.batch_id,format:'csv'})}">Export combined impact (CSV) ↓</a></p>`;}
async function batchDialog(id){if(knownAt){toast('Return to current knowledge to inspect this update.');return;}const b=state.review_batches.find(b=>b.id===id);if(!b)return;const report=await api('/api/batch-impact',{id});modal(`<span class="eyebrow">ONE REVIEW · BOTH SOURCES</span><h1>Federal + state update</h1><p>Effective ${esc(b.evaluation_date)} · Both rates are recorded together.</p>${b.rules.map(c=>{const old=report.previous_rates.find(r=>r.jurisdiction===c.jurisdiction);return `<section class="review-brief"><h2>${esc(c.jurisdiction)} · ${old?fmt(old.amount)+' → ':''}${fmt(c.amount)} <small>AST/hour</small></h2><p>${c.state==='APPROVED'?'Unchanged approved rule — included in this inspection':old&&Number(old.amount)===Number(c.amount)?'Same amount · new rule version or date':'Updated rate'}</p><a href="/api/snapshot?${query({id:c.captured_snapshot_id})}" target="_blank" rel="noopener">Open saved copy ↗</a></section>`;}).join('')}<p>${report.comparison_available?`${report.changed_hourly} hourly workers affected in the combined rate comparison. Final results follow review.`:esc(report.basis)}</p><form id="batch-form" class="review-form"><input type="hidden" name="id" value="${esc(id)}"><label>Your name<input name="actor" required value="${esc(reviewerName)}" autocomplete="name"></label><label class="review-check"><input type="checkbox" name="checked" required>I inspected both saved sources and checked both rates and their effective dates.</label><details><summary>Add a note (required if rejecting)</summary><textarea name="note" rows="2"></textarea></details><div class="actions"><button class="primary" name="decision" value="APPROVED">Approve update</button><button class="secondary" name="decision" value="REJECTED">Reject update</button></div></form><details class="review-details"><summary>Evidence and affected employees</summary>${combinedImpactPanel(report)}</details>`);}

document.addEventListener('submit',async e=>{if(e.target.getAttribute('id')!=='batch-form')return;e.preventDefault();const form=e.target,button=e.submitter;try{const data=Object.fromEntries(new FormData(form));if(button.value==='REJECTED'&&(data.note||'').trim().length<25){form.elements.note.closest('details').open=true;form.elements.note.focus();throw Error('Explain rejection in at least 25 characters');}button.disabled=true;await post('/api/review-batch',{...data,checked:form.elements.checked.checked,decision:button.value});reviewerName=data.actor.trim();$('#detail-dialog').close();await load();toast(failedReevaluations(state.monitor).length?'Combined update recorded. Some re-evaluations need retry.':'Combined update recorded. Results are saved together.');}catch(err){error(err);toast(err.message);button.disabled=false;}});

function dummyForm(runs){return `<section class="panel"><div class="panel-head"><div><h2>Try custom rates</h2><p>Enter both rates to test a scenario. Live results stay unchanged.</p></div><span class="chip amber">DUMMY ONLY</span></div><div class="panel-body"><form id="dummy-form"><div class="form-row"><label>Federal rate · AST/hour<input name="federal" type="number" min="0.01" step="0.01" required></label><label>State rate · AST/hour<input name="state" type="number" min="0.01" step="0.01" required></label></div><div class="form-row"><label>Test date<input name="test_date" type="date" value="${esc(day)}" required></label><label>Test name (optional)<input name="name" maxlength="100" placeholder="e.g. Federal becomes higher"></label></div><button class="primary" type="submit">Run & save dummy test</button></form>${runs.length?`<details class="review-details"><summary>Saved dummy tests (${runs.length})</summary>${runs.map(r=>`<p><button class="link-button" data-dummy="${esc(r.id)}">${esc(r.name)} · ${esc(r.evaluation_date)} · Federal ${fmt(r.federal)} / State ${fmt(r.state)} ↗</button></p>`).join('')}</details>`:''}</div></section>`;}
function dummyDialog(r){const c=r.summary.counts;modal(`<span class="eyebrow">DUMMY TEST · NOT LIVE RESULTS</span><h1>${esc(r.name)}</h1><p>${esc(r.evaluation_date)} · Federal ${fmt(r.federal)} / State ${fmt(r.state)} AST/hour</p><p><b>${c.NON_COMPLIANT||0} below minimum · ${c.COMPLIANT||0} meet minimum · ${(c.REVIEW_REQUIRED||0)+(c.INSUFFICIENT_DATA||0)} need review</b></p><p>${r.baseline_rates?`${r.changes.length} employee results changed compared with federal ${fmt(r.baseline_rates[0])} / state ${fmt(r.baseline_rates[1])} from ${esc(r.baseline_date)}.`:'No approved baseline available; this test shows standalone results.'}</p><p class="muted">Same employees and test date in both calculations. Annual salaries remain review cases. These rates are assumptions, not approved wage rules.</p><a class="secondary small" href="/api/dummy-tests?${query({id:r.id,download:'1'})}">Export dummy JSON ↓</a><details class="review-details" open><summary>Employee test results (${r.results.length})</summary><div class="table-scroll"><table><thead><tr><th>Employee</th><th>Hourly wage</th><th>Test floor</th><th>Dummy result</th></tr></thead><tbody>${r.results.map(e=>`<tr><td>${esc(e.employee_id)}<small>${esc(e.work_jurisdiction)}</small></td><td>${fmt(e.actual_hourly_wage)}</td><td>${fmt(e.controlling_minimum_wage)}</td><td>${chip(e.decision_state)}</td></tr>`).join('')}</tbody></table></div></details>`);}
document.addEventListener('submit',async e=>{if(e.target.getAttribute('id')!=='dummy-form')return;e.preventDefault();const b=e.submitter;try{b.disabled=true;const result=await post('/api/dummy-test',Object.fromEntries(new FormData(e.target)));e.target.reset();dummyDraft=null;await render();dummyDialog(result);toast('Dummy test saved. Live results are unchanged.');}catch(err){error(err);b.disabled=false;}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-dummy]');if(!b)return;try{dummyDialog(await api('/api/dummy-tests',{id:b.dataset.dummy}));}catch(err){error(err);}});

function inspectionDetails(saved){const info=saved.inspection;if(!info)return '';const time=v=>v?new Date(v).toLocaleString():'Not recorded';return `<details class="review-details"><summary>Approval &amp; source details</summary>${saved.legacy?'':`<p><b>Approved by:</b> ${esc(info.actor||'Not recorded')} · ${esc(time(info.reviewed_at))}</p><p><b>Reason:</b> ${esc(info.reason||'Not recorded')}</p>`}<p><b>Employees evaluated:</b> ${info.employees_evaluated}</p>${info.sources.map(r=>`<section class="review-brief"><h3>${esc(r.jurisdiction)} · ${fmt(r.amount)} AST/hour</h3><p>Source captured ${esc(time(r.captured_at))}</p>${saved.legacy?`<p>Approved by ${esc(r.approval?.actor||'Not recorded')} · ${esc(time(r.approval?.reviewed_at))}</p><p>${esc(r.approval?.reason||'No recorded approval reason')}</p>`:''}<a href="/api/snapshot?${query({id:r.snapshot_id})}" target="_blank" rel="noopener">Open saved source ↗</a></section>`).join('')}</details>`;}


